// 1. OBRIGATÓRIO: Importar o useParams e a sua lista de dados
import { useParams } from 'react-router-dom'; 
import ListaCarros from './dados'; // Certifique-se de importar sua lista de carros aqui!

// 2. CORREÇÃO: Remova "props" e "useParams" de dentro dos parênteses ()
function Veiculo() {

    // 3. O useParams é chamado aqui dentro
    const { id } = useParams();

    // Buscamos o carro na lista comparando o ID
    const carro = ListaCarros.find((item) => item.id === parseInt(id));

    if (!carro) {
        return <h2>Carro não encontrado!</h2>;
    }

    return(
        <div className="container mt-5"> 
            <div className="card shadow-sm"> 

                {/* 4. CORREÇÃO CRÍTICA:
                   Não use 'props.imagem'. Use 'carro.imagem'.
                   A variável 'carro' contém os dados que achamos acima. 
                */}
                <img
                    src={carro.imagem} 
                    className="bd-placeholder-img card-img-top" 
                    alt={carro.titulo}
                    width="100%" 
                    height="400"
                    style={{objectFit: "cover"}}
                />    

                <div className="card-body">                
                    <h1 className="display-5">{carro.titulo}</h1> 
                    <p className="fs-3 text-success"><b>R$ {carro.preco}</b></p>

                    <p>Aqui você pode colocar uma descrição detalhada do {carro.titulo}...</p>

                    <button className="btn btn-primary btn-lg mt-3">Comprar Agora</button>
                </div> 
            </div> 
        </div>
    );
}

export default Veiculo;
